// 渲染歌曲列表
function renderSongs() {
  const songGrid = document.getElementById("songGrid");
  if (!songGrid) return;

  const sortByElement = document.getElementById("songSort");
  const sortOrderElement = document.getElementById("sortOrder");
  const sortBy = sortByElement ? sortByElement.value : "dateAdded";
  const sortOrder = sortOrderElement ? sortOrderElement.value : "desc"; // desc=遞減, asc=遞增

  let sortedSongs = [...songs];

  switch (sortBy) {
    case "dateAdded":
      // 按加入日期排序（ID中的時間戳）
      sortedSongs.sort((a, b) => {
        const timeA = parseInt(a.id.replace("song", "")) || 0;
        const timeB = parseInt(b.id.replace("song", "")) || 0;
        return sortOrder === "desc" ? timeB - timeA : timeA - timeB;
      });
      console.log(
        `✅ 按加入日期${sortOrder === "desc" ? "遞減" : "遞增"}排序完成`
      );
      break;
    case "releaseDate":
      // 按發行日期排序 - 統一使用 release_date 欄位
      sortedSongs.sort((a, b) => {
        // 🔴 只使用 release_date 欄位，格式為 YYYY-MM-DD
        const dateA = new Date(a.release_date || "1900-01-01");
        const dateB = new Date(b.release_date || "1900-01-01");

        // 檢查日期是否有效
        if (isNaN(dateA.getTime())) {
          console.warn(
            `無效的發行日期 A: ${a.release_date} (歌曲: ${a.title})`
          );
          dateA.setFullYear(1900, 0, 1);
        }
        if (isNaN(dateB.getTime())) {
          console.warn(
            `無效的發行日期 B: ${b.release_date} (歌曲: ${b.title})`
          );
          dateB.setFullYear(1900, 0, 1);
        }

        // 根據排序方向返回結果
        return sortOrder === "desc"
          ? dateB.getTime() - dateA.getTime()
          : dateA.getTime() - dateB.getTime();
      });

      console.log(
        `✅ 按發行日期${sortOrder === "desc" ? "遞減" : "遞增"}排序完成`
      );
      break;

    case "alphabet":
      // 按字母排序
      sortedSongs.sort((a, b) => {
        const result = a.title.localeCompare(b.title, "zh-TW");
        return sortOrder === "desc" ? -result : result;
      });
      console.log(`✅ 按字母${sortOrder === "desc" ? "遞減" : "遞增"}排序完成`);
      break;

    default:
      console.log("✅ 使用預設排序");
  }

  songGrid.innerHTML = sortedSongs
    .map((song) => {
      const creators = song.creators ? song.creators.join(", ") : "";
      const lyricist = song.lyricist ? song.lyricist.join(", ") : "";
      const composer =
        song.composer && song.composer.length > 0
          ? song.composer.join(", ")
          : "";
      const albums = song.albums || "";

      return `
                <div class="song-card" onclick="showSongDetail('${
                  song.id
                }', 'song')">
                    <img src="${song.image || "images/gray.jpg"}" alt="${
        song.title
      }" />
                    <div class="song-card-content">
                        <div class="song-info">
                            <h3>${song.title}</h3>
                            <p class="creator">${creators}</p>
                            ${
                              albums
                                ? `<p class="album mobile-show">${albums}</p>`
                                : ""
                            }
                        </div>
                        
                        <div class="song-meta desktop-only">
                            ${
                              lyricist
                                ? `<div class="meta-item"><span class="meta-label">作詞：</span>${lyricist}</div>`
                                : ""
                            }
                            ${
                              composer
                                ? `<div class="meta-item"><span class="meta-label">作曲：</span>${composer}</div>`
                                : ""
                            }
                            ${
                              albums
                                ? `<div class="meta-item"><span class="meta-label">專輯：</span>${albums}</div>`
                                : ""
                            }
                        </div>
                        
                        <div class="song-tags">
                            ${
                              song.language
                                ? `<span class="tag tag--language">${song.language}</span>`
                                : ""
                            }
                            ${
                              song.genre
                                ? `<span class="tag tag--genre">${song.genre}</span>`
                                : ""
                            }
                        </div>
                    </div>
                    <div class="song-card-arrow">→</div>
                </div>
            `;
    })
    .join("");

  console.log(
    `✅ 已渲染 ${sortedSongs.length} 首歌曲，排序: ${sortBy} ${sortOrder}`
  );
}

// 渲染詩詞列表
function renderPoems() {
  const poemGrid = document.getElementById("poemGrid");
  poemGrid.innerHTML = poems
    .map(
      (poem) => `
        <div class="song-card" onclick="showSongDetail('${poem.id}', 'poem')">
          <img src="${poems.image || "images/gray.jpg"}" alt="${poem.title}">
          <div class="song-card-content">
            <h3>${poem.title}</h3>
            <p>${poem.creators ? poem.creators.join(", ") : poem.artist}</p>
          </div>
        </div>
      `
    )
    .join("");
}

// 顯示歌曲/詩詞詳情
function showSongDetail(id, type) {
  const data = type === "song" ? songs : poems;
  const item = data.find((s) => s.id === id);
  if (!item) return;

  const songDetail = document.getElementById("songDetail");
  songDetail.innerHTML = `
    <div class="song-detail">
      <a href="#${
        type === "song" ? "songs" : "poems"
      }" class="back-btn" onclick="goBack('${
    type === "song" ? "songs" : "poems"
  }')">← 返回</a>
      <div class="song-detail-header">
        ${item.image ? `<img src="${item.image}" alt="${item.title}">` : ""}
        <h1>${item.title}</h1>
        <p class="artist">${item.creators ? item.creators.join(", ") : ""}</p>
      </div>
      <a href="#" class="favorite-link" onclick="openFavoriteModal('${
        item.id
      }', '${item.title.replace(/'/g, "\\'")}', '${
    item.creators ? item.creators.join(", ").replace(/'/g, "\\'") : ""
  }'); return false;">
  收藏歌詞
</a>
      ${generateSongMeta(item)} 
      <div class="lyrics">${item.lyrics}</div>

       <!-- 🔴 新增刪除按鈕 (只在歌曲頁面顯示) -->
      ${
        type === "song"
          ? `
          <button class="delete-song-btn" onclick="deleteSong('${
            item.id
          }', '${item.title.replace(/'/g, "\\'")}'); return false;">
              刪除歌曲
          </button>
      `
          : ""
      }
    </div>
  `;
  // 切換到詳情頁面
  showPage("songDetail");

  // 顯示前後導航按鈕
  updateNavigationButtons(id, type);
}

// 更新導航按鈕
function updateNavigationButtons(currentId, type) {
  const data = type === "song" ? songs : poems;
  const currentIndex = data.findIndex((s) => s.id === currentId);
  const prevBtn = document.getElementById("prevPostBtn");
  const nextBtn = document.getElementById("nextPostBtn");

  if (currentIndex > 0) {
    prevBtn.style.display = "flex";
    prevBtn.onclick = () => showSongDetail(data[currentIndex - 1].id, type);
  } else {
    prevBtn.style.display = "none";
  }

  if (currentIndex < data.length - 1) {
    nextBtn.style.display = "flex";
    nextBtn.onclick = () => showSongDetail(data[currentIndex + 1].id, type);
  } else {
    nextBtn.style.display = "none";
  }
}

// 返回列表頁面
function goBack(page) {
  showPage(page);
  document.getElementById("prevPostBtn").style.display = "none";
  document.getElementById("nextPostBtn").style.display = "none";
}

// 顯示指定頁面
function showPage(pageId) {
  document.querySelectorAll(".page").forEach((page) => {
    page.classList.remove("active");
  });
  document.getElementById(pageId).classList.add("active");

  // 更新導航連結的 active 狀態
  document.querySelectorAll(".nav-link").forEach((link) => {
    link.classList.remove("active");
    if (link.dataset.page === pageId) {
      link.classList.add("active");
    }
  });

  // 隱藏箭頭按鈕（如果不是詳情頁面）- 加入檢查避免錯誤
  if (pageId !== "songDetail") {
    const prevBtn = document.getElementById("prevPostBtn");
    const nextBtn = document.getElementById("nextPostBtn");
    if (prevBtn) prevBtn.style.display = "none";
    if (nextBtn) nextBtn.style.display = "none";
  }

  // 關閉選單和遮罩
  const nav = document.getElementById("nav");
  const overlay = document.getElementById("overlay");
  if (nav) nav.classList.remove("active");
  if (overlay) overlay.classList.remove("active");
}

// 導航連結點擊事件
document.querySelectorAll(".nav-link").forEach((link) => {
  link.addEventListener("click", (e) => {
    e.preventDefault();
    const page = link.dataset.page;
    showPage(page);

    // 關閉手機版選單
    if (window.innerWidth <= 768) {
      document.getElementById("nav").classList.remove("active");
    }
  });
});

// 手機版選單切換
document.getElementById("menuBtn").addEventListener("click", () => {
  document.getElementById("nav").classList.toggle("active");
});

// 初始化
renderSongs();
renderPoems();

function toggleMenu() {
  const nav = document.getElementById("nav");
  const overlay = document.getElementById("overlay");

  if (nav) nav.classList.toggle("active");
  if (overlay) overlay.classList.toggle("active");
}
function makeCard(item, onClick) {
  const creators = getCreatorsText(item);
  const lyricist = item.lyricist ? item.lyricist.join(", ") : "";
  const composer =
    item.composer && item.composer.length > 0 ? item.composer.join(", ") : "";
  const albums = item.albums || "";

  return `
        <div class="song-card" onclick="${onClick}">
            <img src="${item.image || ""}" alt="${item.title}">
            <div class="song-card-content">
                <div class="song-info">
                    <h3>${item.title}</h3>
                    <p class="creator">${creators}</p>
                    ${
                      albums ? `<p class="album mobile-show">${albums}</p>` : ""
                    }
                </div>
                <div class="song-meta desktop-only">
                    ${
                      lyricist
                        ? `<div class="meta-item"><span class="meta-label">作詞:</span> ${lyricist}</div>`
                        : ""
                    }
                    ${
                      composer
                        ? `<div class="meta-item"><span class="meta-label">作曲:</span> ${composer}</div>`
                        : ""
                    }
                    ${
                      albums
                        ? `<div class="meta-item"><span class="meta-label">專輯:</span> ${albums}</div>`
                        : ""
                    }
                </div>
                <div class="song-card-arrow">→</div>
            </div>
        </div>
    `;
}

// 圖片預覽功能
document.getElementById("songImage")?.addEventListener("change", function (e) {
  const file = e.target.files[0];
  const preview = document.getElementById("imagePreview");

  if (file) {
    const reader = new FileReader();
    reader.onload = function (e) {
      preview.innerHTML = `<img src="${e.target.result}" alt="預覽圖" style="max-width: 200px; border-radius: 8px; margin-top: 10px;">`;
    };
    reader.readAsDataURL(file);
  } else {
    preview.innerHTML = "";
  }
});

// 處理表單提交
document
  .getElementById("uploadForm")
  ?.addEventListener("submit", async function (e) {
    e.preventDefault();

    const statusDiv = document.getElementById("uploadStatus");
    const formData = new FormData(this);

    // 顯示上傳中狀態
    statusDiv.innerHTML =
      '<p style="color: var(--color-primary);">上傳中...</p>';
    statusDiv.className = "upload-status active";

    try {
      const response = await fetch("/api/upload-song", {
        method: "POST",
        body: formData
      });

      const result = await response.json();

      if (response.ok) {
        statusDiv.innerHTML = `<p style="color: var(--color-success);">✅ ${result.message}</p>`;
        this.reset();
        document.getElementById("imagePreview").innerHTML = "";

        // 3秒後重新整理歌曲列表
        setTimeout(() => {
          window.location.reload();
        }, 2000);
      } else {
        statusDiv.innerHTML = `<p style="color: var(--color-error);">❌ ${result.error}</p>`;
      }
    } catch (error) {
      statusDiv.innerHTML = `<p style="color: var(--color-error);">❌ 連線錯誤：${error.message}</p>`;
    }
  });

