// ===== 歌手清單功能 =====

// 提取所有歌手及其歌曲數量
function getArtists() {
  const artistMap = new Map();

  songs.forEach((song) => {
    if (!song || !song.creators) return;

    song.creators.forEach((creator) => {
      const name = creator.trim();
      if (name) {
        if (!artistMap.has(name)) {
          artistMap.set(name, {
            name: name,
            count: 0,
            songs: []
          });
        }
        const artist = artistMap.get(name);
        artist.count++;
        artist.songs.push(song);
      }
    });
  });

  return Array.from(artistMap.values());
}

// 渲染歌手清單
function renderArtists() {
  const artistGrid = document.getElementById("artistGrid");
  if (!artistGrid) return;

  let artists = getArtists();

  // 取得排序方式
  const sortBy = document.getElementById("artistSort")?.value || "count";

  if (sortBy === "count") {
    artists.sort((a, b) => b.count - a.count);
  } else {
    artists.sort((a, b) => a.name.localeCompare(b.name, "zh-TW"));
  }

  artistGrid.innerHTML = artists
    .map((artist) => {
      // 取得歌手名字的第一個字作為頭像
      const initial = artist.name.charAt(0);

      return `
      <div class="artist-card" onclick="showArtistDetail('${artist.name.replace(
        /'/g,
        "\\'"
      )}')">
        <div class="artist-card-avatar">${initial}</div>
        <div class="artist-card-name">${artist.name}</div>
        <div class="artist-card-count">${artist.count} 首歌曲</div>
      </div>
    `;
    })
    .join("");
}

// 顯示單一歌手的詳細資訊
function showArtistDetail(artistName) {
  const artists = getArtists();
  const artist = artists.find((a) => a.name === artistName);

  if (!artist) return;

  // 更新標題
  document.getElementById("artistName").textContent = artist.name;
  document.getElementById(
    "artistSongCount"
  ).textContent = `共 ${artist.count} 首歌曲`;

  // 渲染該歌手的所有歌曲
  const artistSongGrid = document.getElementById("artistSongGrid");
  artistSongGrid.innerHTML = artist.songs
    .filter((song) => song && song.id)
    .map((song) => {
      const creators = song.creators ? song.creators.join(", ") : "";
      const lyricist = song.lyricist ? song.lyricist.join(", ") : "";
      const composer =
        song.composer && song.composer.length > 0
          ? song.composer.join(", ")
          : "";
      const albums = song.albums || "";

      return `
        <div class="song-card" onclick="showSongDetail('${song.id}', 'song')">
          <img src="${song.image || "images/gray.jpg"}" alt="${song.title}">
          <div class="song-card-content">
            <div class="song-info">
              <h3>${song.title}</h3>
              <p class="creator">${creators}</p>
              ${albums ? `<p class="album mobile-show">${albums}</p>` : ""}
            </div>
            <div class="song-meta desktop-only">
              ${
                lyricist
                  ? `<div class="meta-item"><span class="meta-label">作詞:</span> ${lyricist}</div>`
                  : ""
              }
              ${
                composer
                  ? `<div class="meta-item"><span class="meta-label">作曲:</span> ${composer}</div>`
                  : ""
              }
              ${
                albums
                  ? `<div class="meta-item"><span class="meta-label">專輯:</span> ${albums}</div>`
                  : ""
              }
            </div>
            <div class="song-card-arrow">→</div>
          </div>
        </div>
      `;
    })
    .join("");

  showPage("artistDetail");
}

